package com.acrenex.app.activities;
import android.database.Cursor;import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;import com.acrenex.app.database.DatabaseManager;import com.acrenex.app.security.AuthManager;
public class ProfileActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"My Profile","Identity, account and verification status.");DatabaseManager m=new DatabaseManager(this);AuthManager a=new AuthManager(this);Cursor c=m.getDatabase().rawQuery("SELECT name,email,mobile,role,proof_verified FROM users WHERE id=?",new String[]{a.getUserId()});if(c.moveToFirst()){LinearLayout box=utils.column(this);utils.row(box,this,"Name",c.getString(0));utils.row(box,this,"Email",c.getString(1));utils.row(box,this,"Mobile",c.getString(2));utils.row(box,this,"Role",c.getString(3));utils.row(box,this,"Proof",c.getInt(4)==1?"Verified":"Pending");utils.addCard(root,box,this);}c.close();Button logout=new Button(this);logout.setText("Sign out");root.addView(logout);logout.setOnClickListener(v->{a.logout();startActivity(new Intent(this,LoginActivity.class));finishAffinity();});utils.setScreenContentView(this, root);}
}
